UPDATE delivery_statuses SET order_no = 7,  updated_date = NOW(), updated_by = 'system'
WHERE code = 'ordered' AND order_no = 2;
UPDATE delivery_statuses SET order_no = 11, updated_date = NOW(), updated_by = 'system'
WHERE code = 'delivered' AND order_no = 3;
UPDATE delivery_statuses SET order_no = 12, updated_date = NOW(), updated_by = 'system'
WHERE code = 'cancelled' AND order_no = 4;
-- 'new' already holds order_no 1; no update needed.
